// HubAdminServer is the server API for HubAdmin service.
// All implementations must embed UnimplementedHubAdminServer
// for forward compatibility.
type HubAdminServer interface {
	CreateJoinCode(context.Context, *CreateJoinCodeRequest) (*JoinCode, error)
	ListJoinCodes(context.Context, *ListJoinCodesRequest) (*ListJoinCodesResponse, error)
	Approve(context.Context, *NodeRequest) (*NodeInfo, error)
	// Revoke revokes all certificates of the node; workers get the new list
	// with their next heartbeat and reject the node's certificates.
	Revoke(context.Context, *NodeRequest) (*NodeInfo, error)
	SetDrain(context.Context, *SetDrainRequest) (*NodeInfo, error)
	SetLabels(context.Context, *SetLabelsRequest) (*NodeInfo, error)
	PutProfile(context.Context, *Profile) (*Profile, error)
	ListProfiles(context.Context, *ListProfilesRequest) (*ListProfilesResponse, error)
	AssignProfile(context.Context, *AssignProfileRequest) (*NodeInfo, error)
	ListReleases(context.Context, *ListReleasesRequest) (*ListReleasesResponse, error)
	PushRelease(context.Context, *PushReleaseRequest) (*Rollout, error)
	// PublishRelease uploads release files signed on the admin's machine
	// (longarm admin release publish): the hub never holds the private key.
	PublishRelease(grpc.ClientStreamingServer[ReleaseUpload, ReleaseVersion]) error
	GetRollout(context.Context, *GetRolloutRequest) (*Rollout, error)
	AbortRollout(context.Context, *GetRolloutRequest) (*Rollout, error)
	// KillJob kills a job through its worker's hub session (web panel,
	// longarm admin kill).
	KillJob(context.Context, *FleetJobRequest) (*FleetJob, error)
	// JobLogs reads a job's output through its worker's hub session (polling
	// the worker while follow is set). Meant for the panel; longarm logs talks to
	// the worker directly.
	JobLogs(*HubLogsRequest, grpc.ServerStreamingServer[LogChunk]) error
	// SubmitJob runs a command job on a worker ("" / "auto" = placed by the
	// scheduler) through its hub session: no secrets, no repo upload.
	SubmitJob(context.Context, *HubSubmitRequest) (*FleetJob, error)
	// ToolchainApply asks a worker to reconcile its toolchain profile now
	// (longarmd toolchain apply, remotely).
	ToolchainApply(context.Context, *NodeRequest) (*NodeInfo, error)
	// TailnetStatus: the hub's tailnet provider and every node's tailnet
	// state (longarm admin tailnet status).
	TailnetStatus(context.Context, *TailnetStatusRequest) (*TailnetStatusResponse, error)
	// TailnetRekey makes a node drop its tailnet identity and enrol again
	// with a fresh key: pushed to an online worker at once, otherwise on its
	// next hub session (clients: their next hub contact).
	TailnetRekey(context.Context, *NodeRequest) (*TailnetNodeStatus, error)
	// Relays lists the relay set (external relays: connected, last seen) and
	// how many nodes use it (longarm admin relays).
	Relays(context.Context, *RelaysRequest) (*RelaysResponse, error)
	// Users, teams and quotas (multi-tenancy, docs/security.md).
	PutUser(context.Context, *PutUserRequest) (*PutUserResponse, error)
	ListUsers(context.Context, *ListUsersRequest) (*ListUsersResponse, error)
	// RemoveUser revokes every certificate of the user and, with purge, has
	// the workers delete the user's data and OS account.
	RemoveUser(context.Context, *RemoveUserRequest) (*RemoveUserResponse, error)
	SetTeam(context.Context, *SetTeamRequest) (*ListTeamsResponse, error)
	ListTeams(context.Context, *ListTeamsRequest) (*ListTeamsResponse, error)
	mustEmbedUnimplementedHubAdminServer()
}

